/// An import statement extracted from source code.
class ImportInfo {
  /// The module or path being imported from.
  final String source;

  /// Specific names imported from the source module.
  ///
  /// For `import a, b` / `from m import a, b`, every entry's base name
  /// (never the alias). For a JavaScript/TypeScript named-imports clause
  /// (`import { a, b as c } from 'm'`), every specifier's original name.
  ///
  /// Populated for Python and JavaScript/TypeScript only. Always empty for
  /// every other language this crate recognises import statements for —
  /// Rust, Go, Java, Kotlin, and Elixir (`import`/`alias`/`require`/`use`)
  /// — and for a JS/TS namespace import (`import * as ns`) or default
  /// import (`import x from 'm'`), neither of which names individual items.
  final List<String> items;

  /// Alias assigned to the import (e.g., `import numpy as np`).
  ///
  /// Populated for Python's single-name form (`import numpy as np`,
  /// `from m import a as b`) and JavaScript/TypeScript's namespace form
  /// (`import * as ns from 'm'`) or a named-imports clause naming exactly
  /// one specifier (`import { a as b } from 'm'`). `None` for Rust, Go,
  /// Java, Kotlin, and Elixir (which has its own `as:` alias option on
  /// `alias` directives, not yet extracted here) — and for a Python
  /// statement that aliases several names at once (`import os, sys as s`),
  /// where there is no single alias to report for the statement as a
  /// whole, so only `items` is populated for it.
  final String? alias;

  /// Whether this is a wildcard import (e.g., `import *` or `use foo::*`).
  ///
  /// Detected from the syntax tree — a dedicated wildcard node
  /// (`wildcard_import` in Python, `use_wildcard` in Rust) or a bare `*`
  /// token outside of string-literal content — not by searching the
  /// import's source text for a `*` character, so a glob in an import path
  /// string (`import a from './glob*.js'`) is not mistaken for one.
  final bool isWildcard;

  /// Source span covering the import statement.
  final Span span;

  const ImportInfo({
    required this.source,
    required this.items,
    this.alias,
    required this.isWildcard,
    required this.span,
  });

  @override
  int get hashCode =>
      source.hashCode ^
      items.hashCode ^
      alias.hashCode ^
      isWildcard.hashCode ^
      span.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ImportInfo &&
          runtimeType == other.runtimeType &&
          source == other.source &&
          items == other.items &&
          alias == other.alias &&
          isWildcard == other.isWildcard &&
          span == other.span;
}

/// Configuration for the tree-sitter language pack.
///
/// Controls cache directory and which languages to pre-download.
/// Can be loaded from a TOML file, constructed programmatically,
/// or passed as a dict/object from language bindings.
///
/// # Example
///
/// ```no_run
/// use tree_sitter_language_pack::PackConfig;
///
/// let config = PackConfig {
///     cache_dir: None,
///     languages: Some(vec!["python".to_string(), "rust".to_string()]),
///     groups: None,
/// };
/// ```
class PackConfig {
  /// Override the BASE directory the parser cache lives under.
  ///
  /// This is a base, not the final library path: the crate appends
  /// `tree-sitter-language-pack/v{version}/libs` to it, exactly as it does to the
  /// platform default. So `cache_dir = "/tmp/my-parsers"` resolves to
  /// `/tmp/my-parsers/tree-sitter-language-pack/v{version}/libs/`.
  ///
  /// The suffix is not cosmetic. It keeps the whole cache tree — manifest, bundles
  /// and lock file included — inside a directory this crate owns and versions.
  /// Earlier releases used this path verbatim, which put those files in the
  /// configured directory's PARENT and let a cache built by one crate version be
  /// reused by another.
  ///
  /// Default base: the platform cache dir, e.g. `~/.cache` on Linux.
  final String? cacheDir;

  /// Languages to pre-download on init.
  ///
  /// Each entry is a language name (e.g. `"python"`, `"rust"`).
  final List<String>? languages;

  /// Language groups to pre-download.
  ///
  /// Group names come from the remote manifest, so the valid set is not fixed
  /// by this crate; the published manifest currently defines only `"all"`.
  /// Call [`manifest_groups`](crate::manifest_groups) to enumerate them.
  /// An unknown name makes [`init`](crate::init) fail.
  final List<String>? groups;

  const PackConfig({this.cacheDir, this.languages, this.groups});

  @override
  int get hashCode => cacheDir.hashCode ^ languages.hashCode ^ groups.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PackConfig &&
          runtimeType == other.runtimeType &&
          cacheDir == other.cacheDir &&
          languages == other.languages &&
          groups == other.groups;
}

/// A source position — row + column, zero-indexed.
class Point {
  /// Zero-indexed row number.
  final PlatformInt64 row;

  /// Zero-indexed column, counted in **bytes** from the start of the row.
  ///
  /// This is `tree_sitter::Point::column` verbatim, and tree-sitter defines it
  /// as a byte offset — not characters, and not UTF-16 code units. Measured on
  /// a row of the form `x = '<c>'` where `<c>` is a single 4-byte character
  /// (an emoji), the string node reports columns `4..10`, identical to its
  /// byte range; the character columns would be `4..7` and the UTF-16 columns
  /// `4..8`.
  ///
  /// Anything that builds LSP positions (UTF-16) or editor caret columns
  /// (characters) from this field is silently wrong on every row containing a
  /// non-ASCII byte, and must re-measure the row against the source text
  /// instead. Earlier releases documented this field as UTF-16 code units;
  /// that was never what the value contained.
  final PlatformInt64 column;

  const Point({required this.row, required this.column});

  @override
  int get hashCode => row.hashCode ^ column.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Point &&
          runtimeType == other.runtimeType &&
          row == other.row &&
          column == other.column;
}

/// Configuration for the `process()` function.
///
/// Controls which analysis features are enabled and whether chunking is performed.
///
/// # Examples
///
/// ```
/// use tree_sitter_language_pack::ProcessConfig;
///
/// // Defaults: structure + imports + exports enabled
/// let config = ProcessConfig::new("python");
///
/// // With chunking
/// let config = ProcessConfig::new("python").with_chunking(1000);
///
/// // Everything enabled
/// let config = ProcessConfig::new("python").all();
/// ```
class ProcessConfig {
  /// Language name (required).
  final String language;

  /// Extract structural items (functions, classes, etc.). Default: true.
  final bool structure;

  /// Extract import statements. Default: true.
  final bool imports;

  /// Extract export statements. Default: true.
  final bool exports;

  /// Extract comments. Default: false.
  final bool comments;

  /// Extract docstrings. Default: false.
  final bool docstrings;

  /// Extract symbol definitions. Default: false.
  final bool symbols;

  /// Include parse diagnostics. Default: false.
  final bool diagnostics;

  /// Maximum chunk size in bytes. `None` disables chunking.
  ///
  /// `Some(0)` is rejected by [`ProcessConfig::validate`] with
  /// [`Error::InvalidRange`](crate::Error::InvalidRange). A zero-sized chunk
  /// limit previously produced an empty chunk list and silently discarded the
  /// whole source; use `None` to mean "do not chunk".
  final PlatformInt64? chunkMaxSize;

  /// Extract hierarchical key/value data tree from data-format files. Default: false.
  ///
  /// When `true`, [`ProcessResult::data`](crate::ProcessResult::data) is populated
  /// with a [`DataNode`](crate::DataNode) tree for supported languages: JSON, YAML,
  /// TOML, `.properties`, HCL/HOCON, INI, editorconfig, KDL, CUE, CSV, PSV, PO,
  /// nginx config, Caddy config, XML, and DTD.
  ///
  /// For languages outside this set the field is left as `None`.
  ///
  /// # Example
  ///
  /// ```no_run
  /// use tree_sitter_language_pack::{ProcessConfig, process};
  ///
  /// let config = ProcessConfig::new("json").with_data_extraction(true);
  /// let result = process(r#"{"host": "localhost"}"#, &config).unwrap();
  /// assert!(result.data.is_some());
  /// ```
  final bool dataExtraction;

  /// Reject source longer than this many bytes instead of parsing it.
  /// Default: `None` (unbounded).
  ///
  /// Tree-sitter allocates and walks proportionally to input size, so an
  /// unbounded parse of attacker-supplied input is a denial-of-service vector.
  /// The default stays unbounded for backward compatibility; services handling
  /// untrusted input should opt in, e.g. with
  /// [`RECOMMENDED_MAX_SOURCE_BYTES`].
  ///
  /// Exceeding the limit fails the call with
  /// [`Error::InvalidRange`](crate::Error::InvalidRange) — the source is never
  /// silently truncated.
  final PlatformInt64? maxSourceBytes;

  /// Wall-clock budget for the parse step, in milliseconds.
  /// Default: `None` (no timeout).
  ///
  /// Enforced through tree-sitter's parse progress callback, which the parser
  /// invokes periodically; cancellation is therefore granular to that callback
  /// interval rather than exact. A parse that exceeds the budget fails with
  /// [`Error::ParseTimeout`](crate::Error::ParseTimeout).
  final PlatformInt64? parseTimeoutMs;

  const ProcessConfig({
    required this.language,
    required this.structure,
    required this.imports,
    required this.exports,
    required this.comments,
    required this.docstrings,
    required this.symbols,
    required this.diagnostics,
    this.chunkMaxSize,
    required this.dataExtraction,
    this.maxSourceBytes,
    this.parseTimeoutMs,
  });

  @override
  int get hashCode =>
      language.hashCode ^
      structure.hashCode ^
      imports.hashCode ^
      exports.hashCode ^
      comments.hashCode ^
      docstrings.hashCode ^
      symbols.hashCode ^
      diagnostics.hashCode ^
      chunkMaxSize.hashCode ^
      dataExtraction.hashCode ^
      maxSourceBytes.hashCode ^
      parseTimeoutMs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProcessConfig &&
          runtimeType == other.runtimeType &&
          language == other.language &&
          structure == other.structure &&
          imports == other.imports &&
          exports == other.exports &&
          comments == other.comments &&
          docstrings == other.docstrings &&
          symbols == other.symbols &&
          diagnostics == other.diagnostics &&
          chunkMaxSize == other.chunkMaxSize &&
          dataExtraction == other.dataExtraction &&
          maxSourceBytes == other.maxSourceBytes &&
          parseTimeoutMs == other.parseTimeoutMs;
}

/// Complete analysis result from processing a source file.
///
/// Contains metrics, structural analysis, imports/exports, comments,
/// docstrings, symbols, diagnostics, and optionally chunked code segments.
/// Fields are populated based on the `ProcessConfig` flags.
///
/// # Fields
///
/// - `language` - The language used for parsing
/// - `metrics` - Always computed: line counts, byte sizes, error counts
/// - `structure` - Functions, classes, structs (when `config.structure = true`)
/// - `imports` - Import statements (when `config.imports = true`)
/// - `exports` - Export statements (when `config.exports = true`)
/// - `comments` - Comments (when `config.comments = true`)
/// - `docstrings` - Docstrings (when `config.docstrings = true`)
/// - `symbols` - Symbol definitions (when `config.symbols = true`)
/// - `diagnostics` - Parse errors (when `config.diagnostics = true`)
/// - `chunks` - Chunked code segments (when `config.chunk_max_size` is set)
class ProcessResult {
  /// The language name used to parse the source file.
  final String language;

  /// File-level metrics (line counts, byte size, error count).
  final FileMetrics metrics;

  /// Top-level structural items (functions, classes, etc.).
  final List<StructureItem> structure;

  /// Import statements extracted from the source.
  final List<ImportInfo> imports;

  /// Export statements extracted from the source.
  final List<ExportInfo> exports;

  /// Comments extracted from the source.
  final List<CommentInfo> comments;

  /// Docstrings extracted from the source.
  final List<DocstringInfo> docstrings;

  /// Symbol definitions (variables, types, functions) extracted from the source.
  final List<SymbolInfo> symbols;

  /// Parse diagnostics (syntax errors, missing nodes) from tree-sitter.
  final List<Diagnostic> diagnostics;

  /// Syntax-aware code chunks produced when chunking is enabled.
  final List<CodeChunk> chunks;

  /// Hierarchical data tree extracted when `config.data_extraction` is `true`.
  ///
  /// Populated for supported data-format languages (JSON, YAML, TOML, properties,
  /// HCL, INI, XML, CSV, and more). `None` when `data_extraction` is `false` (the
  /// default) or when the language is not a recognised data format.
  ///
  /// See [`DataNode`] for the shape of the returned tree.
  final DataNode? data;

  const ProcessResult({
    required this.language,
    required this.metrics,
    required this.structure,
    required this.imports,
    required this.exports,
    required this.comments,
    required this.docstrings,
    required this.symbols,
    required this.diagnostics,
    required this.chunks,
    this.data,
